import { sql } from 'drizzle-orm';
import { sqliteTable, text, integer } from 'drizzle-orm/sqlite-core';
// MEDIA_CONTENT_TYPES itself lives in packages/contracts — see field-definitions.ts for why.
import type { MediaContentType } from '@kenresoft/contracts';

export type { MediaContentType };

export const media = sqliteTable('media', {
  id: text('id')
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  // R2 object key — generated by the application (§14), never derived from a client-supplied
  // filename.
  key: text('key').notNull().unique(),
  filename: text('filename').notNull(),
  contentType: text('content_type').notNull().$type<MediaContentType>(),
  size: integer('size').notNull(),
  // Null for formats dimension-parsing doesn't cover yet (currently: WebP).
  width: integer('width'),
  height: integer('height'),
  altText: text('alt_text'),
  createdAt: integer('created_at', { mode: 'timestamp' })
    .notNull()
    .default(sql`(unixepoch())`),
  updatedAt: integer('updated_at', { mode: 'timestamp' })
    .notNull()
    .default(sql`(unixepoch())`),
});

export type Media = typeof media.$inferSelect;
export type NewMedia = typeof media.$inferInsert;
